/* test_wav.c — WAV import/export feature tests. Reads test WAVs generated by
 * the Python driver, writes results for Python verification. */
#include "../src/hfe.h"
#include "../src/slots.h"
#include "../src/wavio.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int fails = 0;
#define CHECK(cond, name) do { \
    if (cond) printf("PASS  %s\n", name); \
    else { printf("FAIL  %s\n", name); fails++; } \
} while (0)

static uint8_t *slurp(const char *p, size_t *n)
{
    FILE *f = fopen(p, "rb");
    if (!f) { *n = 0; return NULL; }
    fseek(f, 0, SEEK_END); long l = ftell(f); fseek(f, 0, SEEK_SET);
    uint8_t *b = malloc((size_t)l);
    if (fread(b, 1, (size_t)l, f) != (size_t)l) { free(b); fclose(f); *n=0; return NULL; }
    fclose(f); *n = (size_t)l; return b;
}

static void dump(const char *p, const uint8_t *b, size_t n)
{
    FILE *f = fopen(p, "wb");
    fwrite(b, 1, n, f);
    fclose(f);
}

int main(void)
{
    extern const unsigned char BASE_DISK[];
    extern const unsigned int  BASE_DISK_LEN;
    size_t n;
    uint8_t *w;
    WavImport wi;

    /* 1: 44.1k/16-bit mono 440 Hz sine, 2.0 s -> rate 3 one-shot with marker */
    w = slurp("tw_mono16.wav", &n);
    CHECK(w && wav_import_build(w, n, &wi) == 0, "mono16 imports");
    free(w);
    CHECK(wi.rate == 3 && !wi.truncated && !wi.loop_on, "mono16: rate 3, one-shot");
    CHECK(wi.sendpos == (wi.sendpg + 1) * 2, "mono16: marker at first 256-boundary past audio");
    int zeros = 1;
    for (int i = 0; i < 8; i++) if (wi.sample[(wi.sendpos << 8) + i]) zeros = 0;
    CHECK(zeros, "mono16: 8-zero marker in place");
    CHECK(wi.hdr[213] == 2 && wi.hdr[212] == 3, "mono16: SMPPRE=2 (rate 3), SMPSHFT=3");
    {   /* v0.6: loop region defaults to the whole sample on non-looped imports */
        int p17 = -1, p18 = -1;
        for (int i = 0; i < 52; i++) {
            if (wi.hdr[4+i*4] == 17) p17 = wi.hdr[4+i*4+1];
            if (wi.hdr[4+i*4] == 18) p18 = wi.hdr[4+i*4+1];
        }
        CHECK(p17 == 0 && ((p18*41)>>6) == wi.sendpg,
              "mono16: default loop region = whole sample (params 17/18)");
        CHECK(wi.lend_pg == wi.sendpg, "mono16: lend_pg meta = sendpg");
    }
    {   /* v0.6: forced-rate import */
        size_t n2; uint8_t *w2 = slurp("tw_mono16.wav", &n2);
        WavImport wf;
        CHECK(w2 && wav_import_build_rate(w2, n2, 1, &wf) == 0 && wf.rate == 1,
              "mono16: forced rate 1 honored");
        CHECK(wf.hdr[213] == 8, "mono16 forced: SMPPRE=8 (rate 1)");
        free(w2);
    }
    dump("tw_mono16.sample", wi.sample, SAMPLE_BYTES);
    dump("tw_mono16.hdr", wi.hdr, HDR_BYTES);

    /* 2: stereo 8-bit, 4.5 s -> rate 2 */
    w = slurp("tw_stereo8.wav", &n);
    CHECK(w && wav_import_build(w, n, &wi) == 0, "stereo8 imports");
    free(w);
    CHECK(wi.rate == 2, "stereo8: rate 2 picked (4.5 s)");
    dump("tw_stereo8.sample", wi.sample, SAMPLE_BYTES);
    dump("tw_stereo8.hdr", wi.hdr, HDR_BYTES);

    /* 3: 24-bit with smpl loop -> looped, page-quantized, no marker */
    w = slurp("tw_loop24.wav", &n);
    CHECK(w && wav_import_build(w, n, &wi) == 0, "loop24 imports");
    free(w);
    CHECK(wi.loop_on && wi.sendpos == 0, "loop24: looped, NO end marker (pager rule)");
    printf("info  loop24 pages: lstart %d lend %d sendpg %d unity %d\n",
           wi.lstart_pg, wi.lend_pg, wi.sendpg, wi.unity);
    int nz = 1;
    for (int i = 0; i < SAMPLE_BYTES; i++) if (wi.sample[i] == 0) nz = 0;
    CHECK(nz, "loop24: no $00 anywhere (scrubbed, marker-free)");
    dump("tw_loop24.sample", wi.sample, SAMPLE_BYTES);
    dump("tw_loop24.hdr", wi.hdr, HDR_BYTES);

    /* 4: 12 s float32 -> rate 1 truncated */
    w = slurp("tw_long32f.wav", &n);
    CHECK(w && wav_import_build(w, n, &wi) == 0, "long32f imports");
    free(w);
    CHECK(wi.rate == 1 && wi.truncated && wi.out_n == SAMPLE_BYTES, "long32f: rate 1, truncated");

    /* 5: full pipeline on a disk: import into slot 5 of a new 148 disk,
     * export WAV (with smpl for loops), export .oro */
    HFE h;
    CHECK(hfe_from_mem(&h, BASE_DISK, BASE_DISK_LEN) == 0, "new 148 disk");
    w = slurp("tw_loop24.wav", &n);
    wav_import_build(w, n, &wi);
    free(w);
    CHECK(slot_write_sample(&h, 5, wi.sample) == 0 &&
          slot_write_header(&h, 5, wi.hdr) == 0, "written into slot 5");
    SlotInfo si;
    slot_info(&h, 5, &si);
    CHECK(si.kind == SLOT_V3 && si.has_sample && si.loop_on, "slot 5 parses: V3 + sample + loop");
    CHECK(slot_export_wav(&h, 5, "tw_roundtrip.wav") == 0, "slot 5 -> WAV (smpl expected)");
    CHECK(slot_export_oro(&h, 5, "tw_roundtrip.oro") == 0, "slot 5 -> .oro");

    /* 6: reimport the exported WAV: loop pages must survive the round trip */
    w = slurp("tw_roundtrip.wav", &n);
    WavImport wi2;
    CHECK(w && wav_import_build(w, n, &wi2) == 0, "re-import of exported WAV");
    free(w);
    CHECK(wi2.loop_on && wi2.lstart_pg == wi.lstart_pg && wi2.lend_pg == wi.lend_pg,
          "loop pages survive WAV round trip");
    CHECK(wi2.rate == 3, "rate preserved (9420 in == 9420 out)");
    hfe_free(&h);

    printf(fails ? "\n%d FAILURES\n" : "\nALL WAV TESTS PASSED\n", fails);
    return fails ? 1 : 0;
}
